begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated,service_role;
select no_plan();
update private.admin_execution_environment_v1 set environment='DEVELOPMENT'where singleton;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('a1810000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','delivery-admin-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.platform_user_roles(user_id,role_code)select ('a1810000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=4 then'SUPPORT_AGENT'else'MATRICIA_ADMIN'end from generate_series(1,4)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b1810000-0000-4000-8000-000000000001','Delivery Test','Delivery Test','ACTIVE','a1810000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status)values('c1810000-0000-4000-8000-000000000001','b1810000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000004','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('c1810000-0000-4000-8000-000000000001','CLIENT_OWNER'),('c1810000-0000-4000-8000-000000000001','PROVIDER_OWNER');
create temporary table template_results(k text primary key,v jsonb);grant all on template_results to authenticated;
insert into template_results values('base',jsonb_build_object('hash',private.canonical_request_hash(private.notification_active_pair_v1('SYSTEM_ALERT')))),('notification_count',jsonb_build_object('count',(select count(*)from public.notification_instances where recipient_user_id in('a1810000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000002','a1810000-0000-4000-8000-000000000003','a1810000-0000-4000-8000-000000000004'))));
insert into public.admin_operational_action_requests(id,organization_id,action_type,target_environment,resource_type,resource_id,request_payload_hash,redacted_summary,reason,approvals_required,status,requested_by)select 'e2240000-0000-4000-8000-000000000001',null,'CHANGE_CONFIGURATION','DEVELOPMENT','NOTIFICATION_TEMPLATE','test-template-review-224',repeat('a',64),jsonb_build_object('view','preferences','note',t.id::text,'justification','Review template after actual request fixture'),'Review bilingual template fixture',1,'REQUEST_TRACKED','a1810000-0000-4000-8000-000000000001'from public.notification_template_versions t where template_code='SYSTEM_ALERT'and status='ACTIVE'and locale='fr-MA';
create function pg_temp.notification_translations()returns jsonb language sql immutable as $$select '{"fr-MA":{"subject":"Alerte revue : {{title}}","body":"Texte français revu : {{message}}"},"ar-MA":{"subject":"تنبيه مراجع: {{title}}","body":"نص عربي مراجع: {{message}}"}}'::jsonb$$;
set local role authenticated;select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.preview_notification_template_pair_v1('SYSTEM_ALERT',(select v->>'hash'from template_results where k='base'),pg_temp.notification_translations(),'{"title":"TEST titre","message":"TEST message"}')$$,'42501','NOTIFICATION_TEMPLATE_EDITOR_DENIED','template previews require central MFA');
select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.preview_notification_template_pair_v1('SYSTEM_ALERT',(select v->>'hash'from template_results where k='base'),jsonb_set(pg_temp.notification_translations(),'{fr-MA,body}','"Unknown {{password}}"'),'{"title":"TEST titre","message":"TEST message"}')$$,'22023','UNKNOWN_NOTIFICATION_VARIABLE','editor cannot add unknown or sensitive template variables');
insert into template_results values('preview',public.preview_notification_template_pair_v1('SYSTEM_ALERT',(select v->>'hash'from template_results where k='base'),pg_temp.notification_translations(),'{"title":"TEST titre","message":"TEST message"}'));
insert into template_results values('proposal',public.propose_notification_template_pair_v1('SYSTEM_ALERT',(select v->>'hash'from template_results where k='base'),pg_temp.notification_translations(),'Test revision bilingual security notification',null,'notification224-proposal'));
insert into template_results values('competing',public.propose_notification_template_pair_v1('SYSTEM_ALERT',(select v->>'hash'from template_results where k='base'),pg_temp.notification_translations(),'Competing draft should become stale after another activation',null,'notification224-competing'));
select throws_ok($$select public.decide_notification_template_pair_v1((select(v->>'proposal_id')::uuid from template_results where k='proposal'),(select v->>'content_hash'from template_results where k='proposal'),true,true,'Self approval must fail test','notification224-self')$$,'42501','NOTIFICATION_TEMPLATE_INDEPENDENT_APPROVER_REQUIRED','author cannot activate their own new notification pair');
reset role;
select is((select v#>>'{rendered,0,subject}'from template_results where k='preview'),'تنبيه مراجع: TEST titre','Arabic preview uses the real shared renderer');
select is((select v#>>'{rendered,1,body}'from template_results where k='preview'),'Texte français revu : TEST message','French preview uses exact supplied variable values');
select is((select count(*)from public.notification_template_versions where template_code='SYSTEM_ALERT'and status='DRAFT'and id in(select unnest(draft_template_ids)from public.notification_template_pair_proposals_v1 where id=(select(v->>'proposal_id')::uuid from template_results where k='proposal'))),2::bigint,'proposal persists two genuine inactive versioned templates');
select is((select count(*)from public.notification_template_versions where template_code='SYSTEM_ALERT'and status='ACTIVE'and version=1),2::bigint,'proposal does not retire or change currently active templates');
set local role authenticated;select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.fulfil_notification_template_review_v1('e2240000-0000-4000-8000-000000000001',(select(v->>'proposal_id')::uuid from template_results where k='proposal'),'Real activation must exist before resolving old review')$$,'55000','NOTIFICATION_TEMPLATE_ACTIVATION_PROOF_REQUIRED','a draft proposal cannot fulfil an old tracked review request');
select throws_ok($$select public.decide_notification_template_pair_v1((select(v->>'proposal_id')::uuid from template_results where k='proposal'),repeat('0',64),true,true,'Wrong content hash must fail','notification224-wrong-hash')$$,'40001','STALE_NOTIFICATION_TEMPLATE_PAIR','approval must bind the exact proposed bilingual content');
select throws_ok($$select public.decide_notification_template_pair_v1((select(v->>'proposal_id')::uuid from template_results where k='proposal'),(select v->>'content_hash'from template_results where k='proposal'),true,false,'Missing review attestation must fail','notification224-no-review')$$,'22023','NOTIFICATION_TEMPLATE_BILINGUAL_REVIEW_REQUIRED','activation requires explicit bilingual human review');
insert into template_results values('activated',public.decide_notification_template_pair_v1((select(v->>'proposal_id')::uuid from template_results where k='proposal'),(select v->>'content_hash'from template_results where k='proposal'),true,true,'Reviewed French Arabic texts and exact placeholders','notification224-approve'));
insert into template_results values('replay',public.decide_notification_template_pair_v1((select(v->>'proposal_id')::uuid from template_results where k='proposal'),(select v->>'content_hash'from template_results where k='proposal'),true,true,'Reviewed French Arabic texts and exact placeholders','notification224-approve'));
insert into template_results values('review_requests',public.get_notification_template_review_requests_v1(1)),('editor_console',public.get_notification_template_editor_v1(1));
select public.fulfil_notification_template_review_v1('e2240000-0000-4000-8000-000000000001',(select(v->>'proposal_id')::uuid from template_results where k='proposal'),'Actual reviewed bilingual pair has been activated');
select public.fulfil_notification_template_review_v1('e2240000-0000-4000-8000-000000000001',(select(v->>'proposal_id')::uuid from template_results where k='proposal'),'Actual reviewed bilingual pair has been activated');
reset role;
select is((select v#>>'{requests,0,latestActivatedProposal,id}'from template_results where k='review_requests'),(select v->>'proposal_id'from template_results where k='proposal'),'tracked review has its actual completed activation available regardless of proposal paging');
select ok((select exists(select 1 from jsonb_array_elements(v->'proposals')p where p->>'id'=(select v->>'proposal_id'from template_results where k='proposal')and(p->>'activated')::boolean)from template_results where k='editor_console'),'editor console projects the real activation ledger');
select ok((select exists(select 1 from jsonb_array_elements(v->'proposals')p where p->>'id'=(select v->>'proposal_id'from template_results where k='competing')and(p->>'stale')::boolean)from template_results where k='editor_console'),'competing draft is explicitly marked stale instead of falsely waiting for approval');
select is((select v->>'outcome'from template_results where k='activated'),'NOTIFICATION_TEMPLATE_PAIR_ACTIVATED','independent approval activates both real templates');
select is((select v from template_results where k='activated'),(select v from template_results where k='replay'),'approval replay returns same activation proof');
select is((select count(*)from public.notification_template_versions where template_code='SYSTEM_ALERT'and status='ACTIVE'and version=2),2::bigint,'both locales are active at the new version');
select is((select count(*)from public.notification_template_versions where template_code='SYSTEM_ALERT'and status='RETIRED'and version=1),2::bigint,'old locales remain as immutable retired history');
select is((select count(*)from public.event_outbox where event_type='NotificationTemplatePairActivatedV1'and aggregate_id=(select v->>'proposal_id'from template_results where k='proposal')),1::bigint,'activation event is emitted exactly once');
select is((select status from public.admin_operational_action_requests where id='e2240000-0000-4000-8000-000000000001'),'EXECUTED','tracked review only becomes executed after linked actual bilingual activation');
select is((select count(*)from public.notification_template_review_fulfilments_v1 where action_request_id='e2240000-0000-4000-8000-000000000001'),1::bigint,'review fulfilment proof is immutable and idempotent');
select is((select count(*)from public.notification_instances where recipient_user_id in('a1810000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000002','a1810000-0000-4000-8000-000000000003','a1810000-0000-4000-8000-000000000004')),(select(v->>'count')::bigint from template_results where k='notification_count'),'preview and activation never pretend to send a notification');
update private.admin_execution_environment_v1 set environment='PRODUCTION'where singleton;
insert into template_results values('base2',jsonb_build_object('hash',private.canonical_request_hash(private.notification_active_pair_v1('SYSTEM_ALERT'))));
set local role authenticated;select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.propose_notification_template_pair_v1('SYSTEM_ALERT',(select v->>'hash'from template_results where k='base2'),pg_temp.notification_translations(),'Test production gate missing explicit authorization',null,'notification224-no-prod-reference')$$,'42501','PRODUCTION_AUTHORIZATION_REQUIRED','production has no implicit authorization reference');
insert into template_results values('prod',public.propose_notification_template_pair_v1('SYSTEM_ALERT',(select v->>'hash'from template_results where k='base2'),pg_temp.notification_translations(),'TEST ONLY production configuration policy','TEST-ONLY-AUTHORIZATION-224','notification224-prod'));
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into template_results values('prod-first',public.decide_notification_template_pair_v1((select(v->>'proposal_id')::uuid from template_results where k='prod'),(select v->>'content_hash'from template_results where k='prod'),true,true,'First independent bilingual review TEST ONLY','notification224-prod-first'));
reset role;
select is((select v->>'outcome'from template_results where k='prod-first'),'NOTIFICATION_TEMPLATE_PAIR_APPROVAL_RECORDED','one production approval does not activate templates');
select is((select count(*)from public.notification_template_versions where template_code='SYSTEM_ALERT'and status='ACTIVE'and version=2),2::bigint,'previous production version stays active until second approval');
update private.admin_execution_environment_v1 set environment='DEVELOPMENT'where singleton;
set local role authenticated;select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000003',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.decide_notification_template_pair_v1((select(v->>'proposal_id')::uuid from template_results where k='prod'),(select v->>'content_hash'from template_results where k='prod'),true,true,'Deployment environment mismatch must fail','notification224-prod-wrong-env')$$,'42501','ADMIN_DEPLOYMENT_ENVIRONMENT_MISMATCH','review cannot downgrade environment to bypass production approval');
reset role;update private.admin_execution_environment_v1 set environment='PRODUCTION'where singleton;
set local role authenticated;
insert into template_results values('prod-second',public.decide_notification_template_pair_v1((select(v->>'proposal_id')::uuid from template_results where k='prod'),(select v->>'content_hash'from template_results where k='prod'),true,true,'Second independent bilingual review TEST ONLY','notification224-prod-second'));
reset role;
select is((select v->>'outcome'from template_results where k='prod-second'),'NOTIFICATION_TEMPLATE_PAIR_ACTIVATED','two current independent reviewers activate the production pair');
select is((select count(*)from public.notification_template_versions where template_code='SYSTEM_ALERT'and status='ACTIVE'and version=(select(v->>'version')::integer from template_results where k='prod')),2::bigint,'production activation changes both locales atomically');
select*from finish();rollback;
